.tile__claim,
.tile__beliefs,
.tile__foot {
  flex: none;
}

/* The drawn outline: the fill and the one-pixel line, in the shape that says
 * what kind of claim this is. Sits behind everything in the tile, and takes no
 * clicks. */
.tile__outline {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
}

.tile__outline path {
  fill: var(--surface-raised);
  stroke: var(--hairline);
  stroke-width: 1;
}

/* Two of the four outlines cut into the tile on one side — the hypothesis comes
 * to a point on the left, the dead end is notched on the right — so those two
 * tiles hold their words a step further from that edge. Nothing is ever drawn
 * across a word. */
.tile[data-kind="hypothesis"] {
  padding-left: var(--space-3);
}

.tile[data-kind="not_tradeable"] {
  padding-right: var(--space-3);
}

/* The claim the reader started from is the one thing on the map that did not
 * come from the model, so its outline is drawn in the accent rather than in the
 * hairline. The shape already says it is the hypothesis; this only makes the
 * eye land there first. */

