1	/**
2	 * **A wire's two ends are declared, so no wire waits to be measured.**
3	 *
4	 * The drawing library draws a wire between two ports, and it refuses to draw
5	 * one whose ports it cannot place: `getEdgePosition` returns nothing when
6	 * either end is not initialised, and the whole arrow is then absent from the
7	 * page. Left to itself the library finds a port by measuring the rendered
8	 * tile — through the same size notification a busy browser abandons when too
9	 * many fall due in one frame, and an abandoned one is never delivered. Drop
10	 * every tile's notification and the map draws every claim, in its place, and
11	 * not one arrow. That is the wrong picture of the argument, and a silent one.
12	 * It was met in the wild about once in two hundred runs.
13	 *
14	 * So the ports are handed over, with the box, from the one place that worked
15	 * them out. The library accepts a declared port in place of a measured one, and
16	 * a map whose tiles all say where their ports are is fully drawable on the
17	 * first frame with nothing measured at all.
18	 *
19	 * **Three statements, and the third is the one that matters.** Every wire's two
20	 * ends are declared by name; the ports are placed from the very height the box
21	 * was declared at; and **what the tile draws is what the library was told** —
22	 * because the library keeps measuring afterwards, and a declared number that
23	 * disagreed with the measured one would jump a wire's ends back and forth
24	 * between them every time the map was redrawn.
25	 */
26	
27	import { render } from "@testing-library/react";
28	import { Position, ReactFlowProvider } from "@xyflow/react";
29	import { describe, expect, it } from "vitest";
30	import { Tile } from "../../components/Tile";
31	import { aClaim, aWire, aWorld } from "../../test/aMap";
32	import { TILE_WIDTH } from "../geometry";
33	import { PORTS, type Port, portBox, portsForAWire, portsOf } from "../ports";
34	import { toFlow } from "../toFlow";
35	import { socketsFor } from "../wires/plates";
36	
37	/** The stored example's shape, which is the map every browser test opens. */
38	function stored() {
39	  return aWorld({
40	    hypothesisId: "H",
41	    claims: [
42	      aClaim({ id: "H", kind: "hypothesis", claim: "The Strait of Hormuz reopens." }),
43	      aClaim({ id: "C", claim: "Lloyd's war-risk premium falls below 0.4%." }),
44	      aClaim({ id: "B", claim: "Brent crude settles below $68 for five sessions." }),
45	      aClaim({ id: "R", claim: "OPEC+ announces output restraint." }),
46	      aClaim({ id: "M1", kind: "market", claim: "A Polymarket contract resolves YES." }),
47	    ],
48	    links: [
49	      aWire({ source: "H", target: "C", mode: "sustain" }),
50	      aWire({ source: "C", target: "B" }),
51	      aWire({ source: "B", target: "M1" }),
52	    ],
53	  });
54	}
55	
56	/**
57	 * Where the drawing library will put this end of a wire, from a declared port.
58	 *
59	 * This is the library's own rule, restated in one line so that the check below
60	 * is a check and not a copy: a port on the left edge is attached to at its left
61	 * edge, one on the right at its right edge, and both halfway down their own
62	 * height. (`@xyflow/system`, `getHandlePosition`.)
63	 */
64	function whereTheWireAttaches(height: number, port: Port): { x: number; y: number } {
65	  const box = portBox(height, port);
66	  return {
67	    x: port.edge === Position.Left ? box.x : box.x + box.width,
68	    y: box.y + box.height / 2,
69	  };
70	}
71	
72	describe("no wire waits for a port to be measured", () => {
73	  it("test_every_wire_names_two_ports_the_tiles_declare", () => {
74	    const drawing = toFlow(stored());
75	    expect(drawing.edges.length).toBeGreaterThan(0);
76	
77	    const declared = new Map(drawing.nodes.map((node) => [node.id, node.handles ?? []]));
78	    for (const wire of drawing.edges) {
79	      // The library looks a wire's end up among the source ports of the tile it
80	      // leaves and the target ports of the tile it arrives at, by name. Either
81	      // lookup coming back empty is an arrow that is never drawn.
82	      const leaves = declared
83	        .get(wire.source)
84	        ?.filter((port) => port.type === "source")
85	        .map((port) => port.id);
86	      const arrives = declared
87	        .get(wire.target)
88	        ?.filter((port) => port.type === "target")
89	        .map((port) => port.id);
90	      expect(leaves, `${wire.id} leaves a tile that declared no port to leave from`).toContain(
91	        wire.sourceHandle,
92	      );
93	      expect(arrives, `${wire.id} arrives at a tile that declared no port to land in`).toContain(
94	        wire.targetHandle,
95	      );
96	    }
97	  });
98	
99	  it("test_a_port_is_placed_from_the_height_the_box_was_declared_at", () => {
100	    // Two maps, because a tile's height comes from two places: its own claim,
101	    // and a diff that reserved the taller of two paintings for it so that
102	    // flipping between them moves nothing. A tile that grew has to take its
103	    // ports down with it, or its wires arrive where the tile no longer is.
104	    const taller = new Map([["B", 400]]);
105	    const maps = [toFlow(stored()), toFlow(stored(), taller)];
106	
107	    for (const drawing of maps) {
108	      for (const node of drawing.nodes) {
109	        if (node.type !== "claim") {
110	          // Only a claim is ever at the end of an arrow, so only a claim's tile
111	          // has ports — and the tile standing in for a collapsed column is told
112	          // it has none rather than told the wrong ones.
113	          expect(node.handles).toBeUndefined();
114	          continue;
115	        }
116	        const height = node.initialHeight;
117	        expect(height, `${node.id} did not say how tall it is`).toBeGreaterThan(0);
118	        // Not "both are numbers": the ports the tile declared are the ports
119	        // that height produces, port for port.
120	        expect(node.handles).toEqual(portsOf(height ?? 0));
121	      }
122	    }
123	
124	    // And the map with a taller box really did have one, or the walk above
125	    // compared every tile with itself.
126	    const grew = maps[1]?.nodes.find((node) => node.id === "B");
127	    const asItWas = maps[0]?.nodes.find((node) => node.id === "B");
128	    expect(grew?.initialHeight).toBe(400);
129	    expect(grew?.handles?.[0]?.y).toBeGreaterThan(asItWas?.handles?.[0]?.y ?? 0);
130	  });
131	
132	  it("test_a_declared_port_is_where_the_tile_draws_it", () => {
133	    // A tile as tall as a tile in the stored example, taken from the drawing
134	    // rather than written down, so this cannot drift from what the map draws.
135	    const drawing = toFlow(stored());
136	    const one = drawing.nodes.find((node) => node.type === "claim");
137	    const height = one?.initialHeight ?? 0;
138	    expect(height).toBeGreaterThan(0);
139	
140	    const page = render(
141	      <ReactFlowProvider>
142	        <Tile claim={aClaim({ id: "C" })} isHypothesis={false} height={height} />
143	      </ReactFlowProvider>,
144	    );
145	
146	    const drawn = [...page.container.querySelectorAll<HTMLElement>(".tile__port")];
147	    expect(drawn).toHaveLength(PORTS.length);
148	    for (const [at, port] of PORTS.entries()) {
149	      const box = portBox(height, port);
150	      const element = drawn[at];
151	      expect(element?.dataset.handleid, "the ports are drawn in the declared order").toBe(port.id);
152	      // What is written on the element is what the library was handed. Anything
153	      // else and the wire's ends move by the difference, every time the library
154	      // measures the page and every time the map is redrawn afterwards.
155	      expect(element?.style.left).toBe(`${box.x}px`);
156	      expect(element?.style.top).toBe(`${box.y}px`);
157	      expect(element?.style.width).toBe(`${box.width}px`);
158	      expect(element?.style.height).toBe(`${box.height}px`);
159	      // The library's own stylesheet would otherwise shift a port by half its
160	      // own size and pin it to the edge it is on. Both are said in full above,
161	      // so both are turned off here.
162	      expect(element?.style.transform).toBe("none");
163	      expect(element?.style.right).toBe("auto");
164	    }
165	  });
166	
167	  it("test_a_wire_attaches_where_the_plate_expects_it", () => {
168	    // The plate beside a wire has to be placed before a single wire is drawn,
169	    // so `plates.ts` works out where a wire will start from the layout alone.
170	    // If that ever disagrees with where the library actually attaches it, every
171	    // plate on the map is placed against wires that are somewhere else.
172	    const height = 200;
173	    const cause = { x: 0, y: 0, width: TILE_WIDTH, height };
174	    const effect = { x: 500, y: 40, width: TILE_WIDTH, height };
175	    const boxes = new Map([
176	      ["H", cause],
177	      ["C", effect],
178	    ]);
179	
180	    for (const mode of ["trigger", "sustain"] as const) {
181	      const named = portsForAWire(mode);
182	      const sockets = socketsFor(
183	        { id: "H->C", source: "H", target: "C", handle: named.source, reflexive: false },
184	        boxes,
185	      );
186	      const leaves = PORTS.find((port) => port.id === named.source);
187	      const arrives = PORTS.find((port) => port.id === named.target);
188	      if (leaves === undefined || arrives === undefined) {
189	        throw new Error(`a wire that ${mode}s names a port no tile has`);
