// J2's probe. To run it: copy into frontend/ and `npx vite-node probe-ports.ts`.
// It needs to sit inside frontend/ so that "@xyflow/system" resolves.
// Throwaway probe, deleted straight after running. Not committed.
// Does the installed drawing library place both ends of every wire with nothing
// measured — and does the answer move when a measurement arrives afterwards?
import { adoptUserNodes, getEdgePosition } from "@xyflow/system";
import { toFlow } from "./src/graph/toFlow";
import { aClaim, aWire, aWorld } from "./src/test/aMap";

const world = aWorld({
  hypothesisId: "H",
  claims: [
    aClaim({ id: "H", kind: "hypothesis", claim: "The Strait of Hormuz reopens." }),
    aClaim({ id: "C", claim: "Lloyd's war-risk premium falls below 0.4%." }),
    aClaim({ id: "B", claim: "Brent crude settles below $68 for five sessions." }),
  ],
  links: [
    aWire({ source: "H", target: "C", mode: "sustain" }),
    aWire({ source: "C", target: "B" }),
  ],
});

const drawing = toFlow(world);
const placed = new Map([
  ["H", { x: 0, y: 0 }],
  ["C", { x: 400, y: 40 }],
  ["B", { x: 800, y: 80 }],
]);
const build = () =>
  drawing.nodes.map((node) => ({ ...node, position: placed.get(node.id) ?? { x: 0, y: 0 } }));

function positions(nodes: unknown[] | null, lookup: Map<string, unknown>) {
  const parents = new Map();
  const out =
    nodes === null
      ? { nodesInitialized: "not re-adopted" }
      : // biome-ignore lint: throwaway probe
        adoptUserNodes(nodes as never, lookup as never, parents, { checkEquality: true });
  const found: Record<string, string> = {};
  for (const edge of drawing.edges) {
    const at = getEdgePosition({
      id: edge.id,
      // biome-ignore lint: throwaway probe
      sourceNode: lookup.get(edge.source) as never,
      // biome-ignore lint: throwaway probe
      targetNode: lookup.get(edge.target) as never,
      sourceHandle: edge.sourceHandle ?? null,
      targetHandle: edge.targetHandle ?? null,
      connectionMode: "strict" as never,
      onError: (code: string, message: string) => console.log("   library error", code, message),
    });
    found[edge.id] =
      at === null
        ? "NOT DRAWN"
        : `${at.sourceX},${at.sourceY} -> ${at.targetX},${at.targetY}`;
  }
  return { nodesInitialized: out.nodesInitialized, found };
}

console.log("declared ports on H:", JSON.stringify(drawing.nodes[0]?.handles));

const lookup = new Map();
const first = positions(build(), lookup);
console.log("\n1. first frame, nothing measured  | nodesInitialized:", first.nodesInitialized);
for (const [id, where] of Object.entries(first.found)) console.log(`   ${id}: ${where}`);

// Now the browser delivers. A rendered element's geometry comes back rounded to
// the browser's own layout unit, one sixty-fourth of a pixel, so that is what a
// real measurement of the very box the tile was drawn at would produce.
const toLayoutUnits = (v: number) => Math.round(v * 64) / 64;
for (const [id, node] of lookup) {
  const one = node as { handles?: { type: string }[]; internals: Record<string, unknown> };
  const measured = { source: [], target: [] } as Record<string, unknown[]>;
  for (const handle of one.handles ?? []) {
    const h = handle as Record<string, number | string>;
    measured[h.type as string]?.push({
      ...h,
      nodeId: id,
      x: toLayoutUnits(h.x as number),
      y: toLayoutUnits(h.y as number),
    });
  }
  lookup.set(id, {
    ...one,
    measured: { width: 280, height: 200 },
    internals: { ...one.internals, handleBounds: measured },
  });
}
const measuredNow = positions(null, lookup);
console.log("\n2. the measurement lands          | nodesInitialized:", measuredNow.nodesInitialized);
for (const [id, where] of Object.entries(measuredNow.found)) console.log(`   ${id}: ${where}`);

// And a hover: Canvas builds brand new node objects, so the library re-adopts
// and rebuilds the bounds from what was declared, throwing the measured ones away.
const afterHover = positions(build(), lookup);
console.log("\n3. a hover, declared bounds again  | nodesInitialized:", afterHover.nodesInitialized);
for (const [id, where] of Object.entries(afterHover.found)) console.log(`   ${id}: ${where}`);

let worst = 0;
for (const edge of drawing.edges) {
  const a = first.found[edge.id] ?? "";
  const b = measuredNow.found[edge.id] ?? "";
  const numbers = (s: string) => [...s.matchAll(/-?\d+(\.\d+)?/g)].map((m) => Number(m[0]));
  const left = numbers(a);
  const right = numbers(b);
  left.forEach((n, i) => {
    worst = Math.max(worst, Math.abs(n - (right[i] ?? n)));
  });
}
console.log("\nworst move, declared vs measured, in pixels:", worst);

